SELECT *
FROM system_dept
WHERE enterprise_id = #{enterpriseId}
  AND name = #{name}
  AND delete_flag = 0


where sd.delete_flag = 0
  and se.delete_flag = 0

    and sd.name like concat('%', #{request.name}, '%')


    and sd.status = #{request.status.value}


    and sd.enterprise_id = #{request.enterpriseId}

order by sd.sort
